async reserveCheckout(scopeKey:string,cartIdentity:string,selection?:{operationKind:'RETURN'|'VOID';originalReference:NonNullable<FiscalWorkflowPermitV2['originalReference']>},operationId?:string,options?:FiscalWorkflowReserveOptions):Promise<FiscalWorkflowCheckoutV2>{return this.transaction(async sql=>{
 const current=one(await sql.query('SELECT c.checkout_json,c.checkout_id,c.transaction_id,c.scope_key,c.cart_identity,c.phase,c.permit_id FROM pos_fiscal_checkout_current_v2 p JOIN pos_fiscal_checkouts_v2 c ON c.checkout_id=p.checkout_id WHERE p.scope_key=?',[scopeKey]));
 if(options?.expectedCurrent!==undefined){
  const expected=options.expectedCurrent;let retained:FiscalWorkflowCheckoutV2|null=null;
  try{retained=current?JSON.parse(current.checkout_json):null;}catch{/* Invalid proof remains held. */}
  if(!matchesPreparedRecovery(retained,expected)||expected.scopeKey!==scopeKey||expected.cartIdentity!==cartIdentity||expected.operationId!==operationId
    ||current.checkout_id!==expected.checkoutId||current.transaction_id!==expected.transactionId||current.scope_key!==expected.scopeKey
    ||current.cart_identity!==expected.cartIdentity||current.phase!=='PREPARED')throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
  if(options.requirePermit!==true||!hasPreparedSalePermit(retained!,scopeKey,options.authorityHash))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
  const permit=one(await sql.query('SELECT * FROM pos_fiscal_permits_v2 WHERE permit_id=?',[retained!.permit!.permitId]));
  if(!permit||current.permit_id!==retained!.permit!.permitId||permit.checkout_id!==expected.checkoutId||permit.transaction_id!==expected.transactionId
    ||permit.scope_key!==expected.scopeKey||permit.state!=='RESERVED'||JSON.stringify(JSON.parse(permit.permit_json))!==JSON.stringify(retained!.permit))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
 }
 if(current){const checkout=JSON.parse(current.checkout_json) as FiscalWorkflowCheckoutV2;if(checkout.phase==='ACKNOWLEDGED'&&operationId&&checkout.operationId!==operationId){await sql.run('DELETE FROM pos_fiscal_checkout_current_v2 WHERE scope_key=? AND checkout_id=?',[scopeKey,checkout.checkoutId],false);}else{if(operationId&&checkout.operationId!==operationId&&!['COMMITTED','ACKNOWLEDGED'].includes(checkout.phase))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(selection&&(checkout.permit?.operationKind!==selection.operationKind||JSON.stringify(checkout.permit?.originalReference)!==JSON.stringify(selection.originalReference)))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(options?.requirePermit&&!checkout.permit)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');if(options?.requirePermit&&!['COMMITTED','ACKNOWLEDGED'].includes(checkout.phase)&&(!options.authorityHash||checkout.permit?.authorityHash!==options.authorityHash||!Number.isFinite(Date.parse(checkout.permit?.expiresAt||''))||Date.parse(checkout.permit?.expiresAt||'')<=Date.now()))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(checkout.cartIdentity!==cartIdentity&&checkout.phase!=='COMMITTED')throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');return checkout;}}
 if(options?.requirePermit&&!options.authorityHash)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');
 const pool=one(await sql.query("SELECT * FROM pos_fiscal_permits_v2 WHERE scope_key=? AND state='AVAILABLE' AND expires_at>? AND json_extract(permit_json,'$.operationKind')=? AND (? IS NULL OR json_extract(permit_json,'$.originalReference')=json(?)) AND (? IS NULL OR json_extract(permit_json,'$.authorityHash')=?) ORDER BY expires_at,permit_id LIMIT 1",[scopeKey,new Date().toISOString(),selection?.operationKind||'SALE',selection?JSON.stringify(selection.originalReference):null,selection?JSON.stringify(selection.originalReference):null,options?.authorityHash||null,options?.authorityHash||null]));
 if(selection&&!pool)throw Error('FISCAL_WORKFLOW_REFERENCED_PERMIT_REQUIRED');
 if(options?.requirePermit&&!pool)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');
 const permit=pool?JSON.parse(pool.permit_json) as FiscalWorkflowPermitV2:null,checkout:FiscalWorkflowCheckoutV2={checkoutId:createUuid(),operationId:operationId||createUuid(),transactionId:permit?.transactionId||createUuid(),scopeKey,cartIdentity,permit,phase:'PREPARED',paymentIds:[]};
 if(permit){await sql.run("UPDATE pos_fiscal_permits_v2 SET state='RESERVED',checkout_id=? WHERE permit_id=? AND state='AVAILABLE'",[checkout.checkoutId,permit.permitId],false);if(Number(one(await sql.query('SELECT changes() count'))?.count)!==1)fail();}
 await sql.run('INSERT INTO pos_fiscal_checkouts_v2(checkout_id,transaction_id,scope_key,cart_identity,permit_id,checkout_json,phase)VALUES(?,?,?,?,?,?,?)',[checkout.checkoutId,checkout.transactionId,scopeKey,cartIdentity,permit?.permitId||null,JSON.stringify(checkout),checkout.phase],false);await sql.run('INSERT INTO pos_fiscal_checkout_current_v2(scope_key,checkout_id)VALUES(?,?)',[scopeKey,checkout.checkoutId],false);return checkout;});}

methods.restore:
async restore(): Promise<number> {
    // The explicit manifest selects the restoration path; a failed retained descriptor never falls back.
    if (this.transport.retainedSet) {
      const state = await this.db.getDocument<any>(RECOVERY_STATE, "download");
      if (state) {
        const rows = await this.db.getCollection<any>(RECOVERY_STAGE);
        if (
          rows.some(
            (row) =>
              row.snapshotId === state.snapshot.snapshotId &&
              row.record?.kind === "MEMBERSHIP" &&
              (
                decodeOriginal(
                  new TextDecoder().decode(decodeBase64(row.record.bodyBase64)),
                ) as any
              )?.domain === "pos.retained-capture-set.v1",
          )
        )
          return this.restoreRetained();
      }
    }
    return this.exclusive(async () => {
      const ctx = await this.transport.context(),
        state = await this.db.getDocument<any>(RECOVERY_STATE, "download");
      if (
        !ctx.enabled ||
        !state ||
        state.context !== ctx.key ||
        state.status !== "VERIFIED" ||
        Date.parse(state.snapshot.expiresAt) <= Date.now()
      )
        fail("RECOVERY_NOT_VERIFIED");
      validateSnapshot(state.snapshot);
      const markerId = "import:" + state.snapshot.snapshotId;
      const imported = await this.db.getDocument<any>(RECOVERY_STATE, markerId);
      if (imported) return imported.count;
      const heads = await this.selectedOriginals(state);
      let selection: any = null;
      if (this.transport.pending) {
        selection = await this.transport.pending(state.snapshot.snapshotId);
        const { selectionHash, ...body } = selection;
        if (
          selection.version !== 1 ||
          selection.profile !== "erp.received-native-operations.v1" ||
          selection.snapshot?.snapshotId !== state.snapshot.snapshotId ||
          selection.snapshot?.snapshotDigest !==
            state.snapshot.snapshotDigest ||
          selection.snapshot?.totalRecords !== state.snapshot.totalRecords ||
          selection.coverage !== "RECEIVED_ONLY" ||
          selection.exactZEligible !== false ||
          selection.closeAuthorization !== "NOT_GRANTED" ||
          !ctx.terminalIds.includes(selection.sourceTerminalId) ||
          !ctx.terminalIds.includes(selection.scope?.terminalId) ||
          (ctx.recoveryScope &&
            recoveryCanonicalJson(ctx.recoveryScope) !==
              recoveryCanonicalJson(selection.scope)) ||
          (await originalDigest(bytes(recoveryCanonicalJson(body)))) !==
            selectionHash
        )
          fail("RECOVERY_SELECTION_INVALID");
        if ((await this.transport.context()).key !== ctx.key)
          fail("RECOVERY_SCOPE_CHANGED");
        for (const k of ["pending", "dependencies", "closed", "context"])
          if (!Array.isArray(selection[k])) fail("RECOVERY_SELECTION_INVALID");
        const identities = new Map(heads.map((row) => [row.receiptId, row]));
        const groups = new Map<string, Set<string>>();
        for (const k of ["pending", "dependencies", "closed", "context"]) {
          const seen = new Set<string>();
          groups.set(k, seen);
          for (const entry of selection[k]) {
            const ref = k === "closed" ? entry.reference : entry,
              row = identities.get(ref?.receiptId);
            if (
              !row ||
              seen.has(ref.receiptId) ||
              ref.recordHash !== row.recordHash ||
              [
                "kind",
                "originalId",
                "revision",
                "storageEpoch",
                "bodySha256",
              ].some((field) => ref[field] !== row.record[field]) ||
              (k === "closed" && typeof entry.closeId !== "string")
            )
              fail("RECOVERY_SELECTION_REFERENCE");
            seen.add(ref.receiptId);
          }
        }
        if (
          [...groups.get("pending")!].some(
            (id) =>
              groups.get("closed")!.has(id) ||
              groups.get("dependencies")!.has(id) ||
              groups.get("context")!.has(id),
          ) ||
          new Set([...groups.values()].flatMap((g) => [...g])).size !==
            heads.length
        )
          fail("RECOVERY_SELECTION_COVERAGE");
      }
      const decoded: Array<{ row: any; collection: string; document: any }> =
        [];
      for (const row of heads) {
        if (
          selection &&
          ![
            ...selection.pending,
            ...selection.dependencies,
            ...selection.context,
          ].some((ref) => ref.receiptId === row.receiptId)
        )
          continue;
        const raw = decodeBase64(row.record.bodyBase64);
        if ((await originalDigest(raw)) !== row.record.bodySha256)
          fail("RECOVERY_STAGE_CHANGED");
        const envelope = decodeOriginal(
          new TextDecoder("utf-8", { fatal: true }).decode(raw),
        ) as any;
        if (
          envelope?.version !== 1 ||
          typeof envelope.document !== "string" ||
          typeof envelope.original !== "string"
        )
          fail("RECOVERY_PROFILE_UNSUPPORTED");
        const document = decodeOriginal(envelope.document) as any;
        decodeOriginal(envelope.original); // validates original without replacing runtime aliases
        if (
          !document ||
          document.id !== row.record.originalId ||
          CAPTURE_COLLECTIONS[envelope.collection] !== row.record.kind
        )
          fail("RECOVERY_IDENTITY_MISMATCH");
        decoded.push({ row, collection: envelope.collection, document });
      }
      const closed = new Map<string, string>();
      for (const x of decoded.filter((x) => x.collection === "zReports")) {
        const members = x.document.recoveryMemberIds;
        if (!members) fail("RECOVERY_CLOSE_MEMBERSHIP_UNKNOWN");
        for (const collection of [
          "transactions",
          "cashMovements",
          "collections",
        ]) {
          if (!Array.isArray(members[collection]))
            fail("RECOVERY_CLOSE_MEMBERSHIP_UNKNOWN");
          for (const id of members[collection]) {
            const key = JSON.stringify([collection, id]);
            if (closed.has(key) && closed.get(key) !== x.document.id)
              fail("RECOVERY_MULTIPLE_CLOSES");
            closed.set(key, x.document.id);
          }
        }
      }
      if (selection)
        for (const item of selection.closed) {
          const row = heads.find(
            (r) => r.receiptId === item.reference.receiptId,
          )!;
          const collection = Object.keys(CAPTURE_COLLECTIONS).find(
            (k) =>
              k !== "transactionHistory" &&
              CAPTURE_COLLECTIONS[k] === row.record.kind,
          )!;
          const identity = JSON.stringify([collection, row.record.originalId]);
          if (closed.has(identity) && closed.get(identity) !== item.closeId)
            fail("RECOVERY_MULTIPLE_CLOSES");
          closed.set(identity, item.closeId);
        }
      const mutations: DurableDocumentMutation[] = [];
      if (selection)
        mutations.push({
          collectionName: RECOVERY_STATE,
          document: {
            id: "pendingSelection:" + state.snapshot.snapshotId,
            body: selection,
          },
        });
      for (const { row, collection, document } of decoded) {
        const closeId =
          closed.get(JSON.stringify([collection, document.id])) ||
          document.zReportId;
        const destination =
          collection === "transactions" && closeId
            ? "transactionHistory"
            : collection;
        const restored = {
          ...document,
          ...(closeId ? { zReportId: closeId } : {}),
          _posRecovery: {
            snapshotId: state.snapshot.snapshotId,
            receiptId: row.receiptId,
            bodySha256: row.record.bodySha256,
            businessApplication: "UNKNOWN",
            ...(selection && closeId ? { provenCloseId: closeId } : {}),
            exactZEligible: false,
            closeAuthorization: "NOT_GRANTED",
          },
        };
        if (collection === "transactions") {
          const other =
            destination === "transactions"
              ? "transactionHistory"
              : "transactions";
          if (await this.db.getDocument(other, document.id))
            fail("RECOVERY_LOCAL_CONFLICT:" + other + ":" + document.id);
        }
        const current = await this.db.getDocument<any>(
          destination,
          document.id,
        );
        if (current?._posRecovery?.bodySha256 === row.record.bodySha256)
          continue;
        if (current)
          fail("RECOVERY_LOCAL_CONFLICT:" + destination + ":" + document.id);
        mutations.push({ collectionName: destination, document: restored });
      }
      // Preserve original staging and pending local work; no inventory/customer/series writes.
      mutations.push({
        collectionName: RECOVERY_STATE,
        document: {
          id: markerId,
          count: mutations.filter((m) => m.collectionName !== RECOVERY_STATE)
            .length,
          snapshotId: state.snapshot.snapshotId,
          exactZEligible: false,
          closeAuthorization: "NOT_GRANTED",
        },
      });
      if ((await this.transport.context()).key !== ctx.key)
        fail("RECOVERY_SCOPE_CHANGED");
      await this.commit(mutations, true);
      return mutations.filter((m) => m.collectionName !== RECOVERY_STATE)
        .length;
    });
  }

methods.isOperationalSyncPending:
private isOperationalSyncPending(item: any, collectionName: string): boolean {
        if (isRecoveredOperation(item)) return false;
        const retryAfter = Date.parse(String(item?.syncRetryAfter || ''));
        if (Number.isFinite(retryAfter) && retryAfter > Date.now()) {
            const delay = Math.max(1000, retryAfter - Date.now());
            this.nextRetryDelayMs = this.nextRetryDelayMs === null
                ? delay
                : Math.min(this.nextRetryDelayMs, delay);
            return false;
        }

        const status = item?.syncStatus;
        if (collectionName === 'catalogEdits' && status === 'PENDING') {
            const nextAttemptAt = Number(item?.nextAttemptAt);
            if (Number.isFinite(nextAttemptAt) && nextAttemptAt > Date.now()) {
                const delay = Math.max(1000, nextAttemptAt - Date.now());
                this.nextRetryDelayMs = this.nextRetryDelayMs === null
                    ? delay
                    : Math.min(this.nextRetryDelayMs, delay);
            }
        }
        if (status === 'PENDING') return true;
        if (status === 'RETRY_WAIT') return true;
        if (status === 'SYNCING') {
            const startedAt = Date.parse(String(item?.syncStartedAt || ''));
            return Number.isFinite(startedAt) && Date.now() - startedAt > this.STUCK_SYNCING_TIMEOUT_MS;
        }
        if (
            status === 'ERROR' ||
            status === 'SYNCED_CLOUD' ||
            status === 'SYNCED_ACTIVE' ||
            status === 'SYNCED_MASTER' ||
            status === 'APPLIED_ERP' ||
            status === 'BLOCKED_FUNCTIONAL' ||
            status === 'FAILED_FINAL'
        ) return false;

        if (collectionName === 'transactions' && (status === undefined || status === null || status === '')) {
            return true;
        }
        if (
            (collectionName === 'wallet_transactions' || collectionName === 'loyalty_events') &&
            (status === undefined || status === null || status === '')
        ) {
            return false;
        }
        return false;
    }

methods.processCollection:
private async processCollection<T extends {
        id: string,
        syncStatus?: SyncStatus,
        syncError?: string,
        _forceSyncReplay?: boolean,
        syncRetryAfter?: string,
        createdAt?: string,
        timestamp?: string,
        date?: string,
        closedAt?: string,
        openedAt?: string,
        updatedAt?: string
    }>(
        collectionName: string,
        pushFn: (item: T) => Promise<any>
    ) {
        const generation = this.remoteGeneration;
        if (!this.remoteEnabled || isPosSaleActive()) return;
        const data = await db.get(collectionName as any) as T[];
        if (!Array.isArray(data)) return;

        // Filter pending items and sort by date (FIFO)
        const pending = data.filter(item =>
            !isFormatOwnedDocument(item) && !isRecoveredOperation(item) && (this.shouldSyncItem(collectionName, item) || (collectionName === 'transactions' && item._forceSyncReplay === true)) &&
            this.isOperationalSyncPending(item, collectionName)
        );

        if (pending.length === 0) {
            return;
        }

        console.log(`🔄 BackgroundSyncManager: Processing ${pending.length} pending items in ${collectionName}`);

        // Sort by date to maintain integrity
        pending.sort((a, b) => {
            const dateA = this.resolveItemDate(a)?.getTime() ?? 0;
            const dateB = this.resolveItemDate(b)?.getTime() ?? 0;
            return dateA - dateB;
        });

        for (const item of pending) {
            if (!this.remoteEnabled || generation !== this.remoteGeneration) return;
            if (isPosSaleActive()) {
                console.log(`⏸️ BackgroundSyncManager: ${collectionName} paused for active POS input.`);
                return;
            }

            try {
                // Mark as syncing
                item.syncStatus = 'SYNCING';
                (item as any).syncStartedAt = new Date().toISOString();
                delete (item as any).syncRetryAfter;
                await db.saveDocument(collectionName as any, item as any);

                // Attempt push
                const mutationResult = await pushFn(item);
                if (!this.remoteEnabled || generation !== this.remoteGeneration) {
                    console.warn(`🛑 BackgroundSyncManager: Ignoring stale ACK for ${collectionName} item ${item.id}.`);
                    return;
                }
                authenticatedActivityTracker.record('PUSH');
                syncMetrics.increment('pushes_total');
                authenticatedActivityTracker.record('ACK');
                syncMetrics.increment('ack_total');
                syncMetrics.markAckFinished();

                const targetKind = syncPolicy.targetKind();
                if (targetKind === 'ERP_ACTIVE') {
                    syncMetrics.markErpApplied();
                    syncMetrics.markApplyFinished();
                }
                // Mark as completed
                item.syncStatus = targetKind === 'POS_CLOUD_STAGING'
                    ? 'SYNCED_CLOUD'
                    : targetKind === 'ERP_ACTIVE'
                        ? 'APPLIED_ERP'
                        : targetKind === 'POS_MASTER'
                            ? 'SYNCED_MASTER'
                            : 'COMPLETED';
                item.syncError = undefined;
                (item as any).syncBlockedReason = undefined;
                (item as any).syncBlockedAt = undefined;
                if (item._forceSyncReplay) {
                    item._forceSyncReplay = false;
                }
                delete (item as any).syncRetryAfter;
                delete (item as any).syncStartedAt;
                await db.saveDocument(collectionName as any, item as any);
                await completeLegacyMutationAfterDurableAck(
                    mutationResult,
                    `BackgroundSyncManager:${collectionName}:${item.id}`,
                );
                if (collectionName === 'transactions') {
                    const transaction = item as any;
                    console.log(
                        `[SYNC_BSM] marked COMPLETED collection=transactions id=${transaction.id} source_transaction_id=${transaction.source_transaction_id || 'n/a'}`
                    );
                }
                await this.yieldToOperatorUi();
            } catch (error: any) {
                if (!this.remoteEnabled || generation !== this.remoteGeneration) return;
                if (collectionName === 'transactions' && this.isRecoverableTransactionSyncError(error)) {
                    console.warn(
                        `⏳ BackgroundSyncManager: Deferred recoverable transaction sync ${item.id}:`,
                        error?.message || error
                    );
                    item.syncStatus = 'RETRY_WAIT';
                    syncMetrics.increment('retry_count');
                    item.syncError = undefined;
                    item._forceSyncReplay = true;
                    (item as any).syncRetryAfter = new Date(Date.now() + this.RECOVERABLE_TRANSACTION_RETRY_DELAY_MS).toISOString();
                    delete (item as any).syncStartedAt;
                    this.nextRetryDelayMs = this.nextRetryDelayMs === null
                        ? this.RECOVERABLE_TRANSACTION_RETRY_DELAY_MS
                        : Math.min(this.nextRetryDelayMs, this.RECOVERABLE_TRANSACTION_RETRY_DELAY_MS);
                    await db.saveDocument(collectionName as any, item as any);
                    break;
                }

                if (this.isFunctionalSyncError(error)) {
                    console.error(`🚧 BackgroundSyncManager: Functional sync block ${collectionName} item ${item.id}:`, error);
                    item.syncStatus = 'BLOCKED_FUNCTIONAL';
                    item.syncError = error?.message || String(error || 'Functional sync error');
                    (item as any).syncBlockedReason = item.syncError;
                    (item as any).syncBlockedAt = new Date().toISOString();
                    if (item._forceSyncReplay) {
                        item._forceSyncReplay = false;
                    }
                    delete (item as any).syncRetryAfter;
                    delete (item as any).syncStartedAt;
                    await db.saveDocument(collectionName as any, item as any);
                    continue;
                }

                console.error(`❌ BackgroundSyncManager: Failed to sync ${collectionName} item ${item.id}:`, error);
                item.syncStatus = 'RETRY_WAIT';
                syncMetrics.increment('retry_count');
                item.syncError = error.message;
                (item as any).syncRetryAfter = new Date(Date.now() + this.RECOVERABLE_TRANSACTION_RETRY_DELAY_MS).toISOString();
                delete (item as any).syncStartedAt;
                await db.saveDocument(collectionName as any, item as any);

                // Stop processing this collection to maintain FIFO order on next retry
                throw error;
            }
        }
    }

